  // Aging Report - Accounts Receivable by age
  async getAgingReport(filters = {}, months = null) {
    try {
      const baseQuery = supabase
        .from('bills')
        .select('billid, customerid, billedmonth, totalbillamount')
        .eq('paymentstatus', 'Unpaid')

      const data = await fetchAllRecords(baseQuery)

      // Fetch customer details to get barangay, type, status
      const customerIds = [...new Set(data.map(b => b.customerid).filter(id => id))]
      let customerMap = {}
      if (customerIds.length > 0) {
        const baseQueryCustomers = supabase
          .from('customers')
          .select('customerid, name, address, barangay, type, status')
          .in('customerid', customerIds)
        
        const customers = await fetchAllRecords(baseQueryCustomers)
        if (customers) {
          customers.forEach(c => {
            customerMap[c.customerid] = c
          })
        }
      }

      // Merge customer info into data
      const mergedData = data.map(bill => {
        const customer = customerMap[bill.customerid] || {}
        return {
          ...bill,
          barangay: customer.barangay || 'Unknown',
          type: customer.type || 'Unknown',
          status: customer.status || 'Unknown'
        }
      })

      // Apply filters if provided
      let filteredData = mergedData
      if (filters.barangay) {
        if (Array.isArray(filters.barangay)) {
          if (filters.barangay.length > 0 && !filters.barangay.includes('all')) {
            filteredData = filteredData.filter(b => filters.barangay.includes(b.barangay))
          }
        } else if (filters.barangay !== 'all') {
          filteredData = filteredData.filter(b => b.barangay === filters.barangay)
        }
      }
      if (filters.type) {
        if (Array.isArray(filters.type)) {
          if (filters.type.length > 0 && !filters.type.includes('all')) {
            filteredData = filteredData.filter(b => filters.type.includes(b.type))
          }
        } else if (filters.type !== 'all') {
          filteredData = filteredData.filter(b => b.type === filters.type)
        }
      }
      if (filters.status && filters.status !== 'all') {
        filteredData = filteredData.filter(b => b.status === filters.status)
      }
      if (months && months.length > 0) {
        filteredData = filteredData.filter(b => months.includes(b.billedmonth))
      }

      const today = new Date()
      today.setHours(0, 0, 0, 0)

      const aging = {
        current: [],      // 0-30 days
        days_31_60: [],   // 31-60 days
        days_61_90: [],   // 61-90 days
        days_91_120: [],  // 91-120 days
        over_120: []      // Over 120 days
      }

      filteredData.forEach(bill => {
        const billDate = new Date(bill.billedmonth)
        const daysDiff = Math.floor((today - billDate) / (1000 * 60 * 60 * 24))

        if (daysDiff <= 30) aging.current.push(bill)
        else if (daysDiff <= 60) aging.days_31_60.push(bill)
        else if (daysDiff <= 90) aging.days_61_90.push(bill)
        else if (daysDiff <= 120) aging.days_91_120.push(bill)
        else aging.over_120.push(bill)
      })

      const summary = {
        current: {
          count: aging.current.length,
          amount: aging.current.reduce((sum, b) => sum + parseFloat(b.totalbillamount || 0), 0)
        },
        days_31_60: {
          count: aging.days_31_60.length,
          amount: aging.days_31_60.reduce((sum, b) => sum + parseFloat(b.totalbillamount || 0), 0)
        },
        days_61_90: {
          count: aging.days_61_90.length,
          amount: aging.days_61_90.reduce((sum, b) => sum + parseFloat(b.totalbillamount || 0), 0)
        },
        days_91_120: {
          count: aging.days_91_120.length,
          amount: aging.days_91_120.reduce((sum, b) => sum + parseFloat(b.totalbillamount || 0), 0)
        },
        over_120: {
          count: aging.over_120.length,
          amount: aging.over_120.reduce((sum, b) => sum + parseFloat(b.totalbillamount || 0), 0)
        }
      }

      const totalAmount = Object.values(summary).reduce((sum, s) => sum + s.amount, 0)
      const totalCount = Object.values(summary).reduce((sum, s) => sum + s.count, 0)

      return {
        success: true,
        data: {
          summary,
          totalAmount,
          totalCount,
          details: aging
        }
      }
    } catch (error) {
      console.error('Error getting aging report:', error)
      return { success: false, error: error.message }
    }
  },

