import React, { useState, useEffect } from 'react';
import { mcrService } from '../../../../services/mcrService';
import {
  Box,
  Container,
  Grid,
  Paper,
  Typography,
  Button,
  IconButton,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  Chip,
  Alert,
  Snackbar,
  CircularProgress,
  useTheme,
  InputAdornment,
  Divider,
  Stack
} from '@mui/material';
import {
  AccessTime,
  Refresh,
  CheckCircle,
  Error as ErrorIcon,
  RequestQuote,
  Visibility,
  AttachMoney,
  Person,
  ListAlt,
  Receipt,
  Description
} from '@mui/icons-material';

const MunicipalCivilRegistryHome = ({ user }) => {
  const theme = useTheme();
  const [pendingOrders, setPendingOrders] = useState([]);
  const [paidOrders, setPaidOrders] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [viewingOrder, setViewingOrder] = useState(null);
  const [processingPayment, setProcessingPayment] = useState(null);
  const [orNumber, setOrNumber] = useState('');

  useEffect(() => {
    loadOrders();
  }, []);

  const loadOrders = async () => {
    setLoading(true);
    const result = await mcrService.getAllOrders();
    if (result.success) {
      // Filter pending and paid orders
      const pending = result.data.filter(order => order.status === 'pending');
      const paid = result.data.filter(order => order.status === 'paid')
        .slice(0, 10); // Show only 10 most recent paid orders
      setPendingOrders(pending);
      setPaidOrders(paid);
    } else {
      setError(result.error);
    }
    setLoading(false);
  };

  const calculateAge = (birthdate) => {
    if (!birthdate) return '';
    const today = new Date();
    const birth = new Date(birthdate);
    let age = today.getFullYear() - birth.getFullYear();
    const monthDiff = today.getMonth() - birth.getMonth();
    if (monthDiff < 0 || (monthDiff === 0 && today.getDate() < birth.getDate())) {
      age--;
    }
    return age;
  };

  const handleViewOrder = async (order) => {
    setLoading(true);
    const result = await mcrService.getOrderWithItems(order.id);
    if (result.success) {
      setViewingOrder(result.data);
    } else {
      setError(result.error);
    }
    setLoading(false);
  };

  const openPaymentModal = (order) => {
    setProcessingPayment(order);
    setOrNumber('');
  };

  const handleProcessPayment = async () => {
    if (!orNumber.trim()) {
      setError('Please enter OR Number');
      return;
    }

    setLoading(true);
    // Get the current user's full name
    const processedBy = `${user.firstname} ${user.lastname}`;
    const result = await mcrService.updateOrderStatus(processingPayment.id, 'paid', orNumber, processedBy);
    
    if (result.success) {
      setSuccess(`Payment processed successfully! OR #${orNumber}`);
      setProcessingPayment(null);
      setOrNumber('');
      loadOrders();
    } else {
      setError(result.error);
    }
    setLoading(false);
  };

  return (
    <Box sx={{ flexGrow: 1, pb: 4 }}>
      <Container maxWidth="xl">
        {/* Welcome Section */}
        <Box sx={{ mb: 4 }}>
          <Typography variant="h4" gutterBottom fontWeight="bold" color="primary">
            Welcome to Municipal Civil Registry, {user?.firstname}! 👋
          </Typography>
          <Typography variant="subtitle1" color="text.secondary">
            Municipal Civil Registry Management System
          </Typography>
        </Box>

        {/* Pending Orders Header */}
        <Paper
          elevation={0}
          sx={{
            p: 3,
            mb: 3,
            background: `linear-gradient(135deg, ${theme.palette.primary.main} 0%, ${theme.palette.primary.dark} 100%)`,
            color: 'white',
            borderRadius: 2,
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'center',
            flexWrap: 'wrap',
            gap: 2
          }}
        >
          <Box>
            <Box sx={{ display: 'flex', alignItems: 'center', mb: 1 }}>
              <AccessTime sx={{ mr: 1 }} />
              <Typography variant="h5" fontWeight="bold">
                Pending Orders of Payment
              </Typography>
            </Box>
            <Typography variant="body1" sx={{ opacity: 0.9 }}>
              {pendingOrders.length} order{pendingOrders.length !== 1 ? 's' : ''} awaiting payment
            </Typography>
          </Box>
          <Button
            variant="contained"
            color="secondary"
            startIcon={<Refresh />}
            onClick={loadOrders}
            disabled={loading}
            sx={{ bgcolor: 'rgba(255,255,255,0.2)', '&:hover': { bgcolor: 'rgba(255,255,255,0.3)' } }}
          >
            Refresh
          </Button>
        </Paper>

        {/* Pending Orders List */}
        {pendingOrders.length === 0 && !loading ? (
          <Paper
            elevation={0}
            sx={{
              p: 6,
              textAlign: 'center',
              bgcolor: '#f0fdf4',
              border: '2px dashed #bbf7d0',
              borderRadius: 2,
              mb: 4
            }}
          >
            <CheckCircle sx={{ fontSize: 60, color: 'success.main', mb: 2 }} />
            <Typography variant="h5" color="text.primary" gutterBottom>
              All Caught Up!
            </Typography>
            <Typography variant="body1" color="text.secondary">
              No pending orders of payment at the moment
            </Typography>
          </Paper>
        ) : (
          <TableContainer component={Paper} sx={{ mb: 4, borderRadius: 2 }}>
            <Table>
              <TableHead sx={{ bgcolor: 'grey.100' }}>
                <TableRow>
                  <TableCell>Order #</TableCell>
                  <TableCell>Client Name</TableCell>
                  <TableCell>Age</TableCell>
                  <TableCell>Address</TableCell>
                  <TableCell>Total Amount</TableCell>
                  <TableCell>Date</TableCell>
                  <TableCell align="right">Actions</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {pendingOrders.map((order) => (
                  <TableRow key={order.id} hover>
                    <TableCell sx={{ fontWeight: 'bold', color: 'primary.main' }}>
                      {order.order_number}
                    </TableCell>
                    <TableCell>{order.client?.name || 'N/A'}</TableCell>
                    <TableCell>
                      {order.client?.birthdate
                        ? `${calculateAge(order.client?.birthdate)} years`
                        : (order.client?.age ? `${order.client.age} years` : 'N/A')}
                    </TableCell>
                    <TableCell sx={{ maxWidth: 200, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                      {order.client?.address || 'N/A'}
                    </TableCell>
                    <TableCell>
                      <Chip
                        label={`₱${parseFloat(order.total_amount).toFixed(2)}`}
                        color="warning"
                        variant="outlined"
                        size="small"
                        sx={{ fontWeight: 'bold' }}
                      />
                    </TableCell>
                    <TableCell>{new Date(order.created_at).toLocaleDateString()}</TableCell>
                    <TableCell align="right">
                      <Stack direction="row" spacing={1} justifyContent="flex-end">
                        <Button
                          size="small"
                          variant="outlined"
                          startIcon={<Visibility />}
                          onClick={() => handleViewOrder(order)}
                        >
                          View
                        </Button>
                        <Button
                          size="small"
                          variant="contained"
                          color="success"
                          startIcon={<AttachMoney />}
                          onClick={() => openPaymentModal(order)}
                        >
                          Pay
                        </Button>
                      </Stack>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </TableContainer>
        )}

        {/* Recent Paid Orders Header */}
        <Paper
          elevation={0}
          sx={{
            p: 3,
            mb: 3,
            background: `linear-gradient(135deg, ${theme.palette.secondary.main} 0%, ${theme.palette.secondary.dark} 100%)`,
            color: 'white',
            borderRadius: 2
          }}
        >
          <Box>
            <Box sx={{ display: 'flex', alignItems: 'center', mb: 1 }}>
              <CheckCircle sx={{ mr: 1 }} />
              <Typography variant="h5" fontWeight="bold">
                Recent Paid Orders
              </Typography>
            </Box>
            <Typography variant="body1" sx={{ opacity: 0.9 }}>
              Last {paidOrders.length} completed payment{paidOrders.length !== 1 ? 's' : ''}
            </Typography>
          </Box>
        </Paper>

        {/* Paid Orders List */}
        {paidOrders.length === 0 && !loading ? (
          <Paper
            elevation={0}
            sx={{
              p: 6,
              textAlign: 'center',
              bgcolor: '#eff6ff',
              border: '2px dashed #bfdbfe',
              borderRadius: 2
            }}
          >
            <RequestQuote sx={{ fontSize: 60, color: 'primary.main', mb: 2 }} />
            <Typography variant="h5" color="text.primary" gutterBottom>
              No Paid Orders Yet
            </Typography>
            <Typography variant="body1" color="text.secondary">
              Completed payments will appear here
            </Typography>
          </Paper>
        ) : (
          <TableContainer component={Paper} sx={{ borderRadius: 2 }}>
            <Table>
              <TableHead sx={{ bgcolor: 'grey.100' }}>
                <TableRow>
                  <TableCell>Order #</TableCell>
                  <TableCell>OR Number</TableCell>
                  <TableCell>Client Name</TableCell>
                  <TableCell>Age</TableCell>
                  <TableCell>Total Amount</TableCell>
                  <TableCell>Payment Date</TableCell>
                  <TableCell>Processed By</TableCell>
                  <TableCell align="right">Actions</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {paidOrders.map((order) => (
                  <TableRow key={order.id} hover>
                    <TableCell sx={{ fontWeight: 'bold', color: 'primary.main' }}>
                      {order.order_number}
                    </TableCell>
                    <TableCell>
                      <Chip
                        label={order.or_number || 'N/A'}
                        color="success"
                        size="small"
                      />
                    </TableCell>
                    <TableCell>{order.client?.name || 'N/A'}</TableCell>
                    <TableCell>
                      {order.client?.birthdate
                        ? `${calculateAge(order.client?.birthdate)} years`
                        : (order.client?.age ? `${order.client.age} years` : 'N/A')}
                    </TableCell>
                    <TableCell>
                      <Chip
                        label={`₱${parseFloat(order.total_amount).toFixed(2)}`}
                        color="primary"
                        variant="outlined"
                        size="small"
                        sx={{ fontWeight: 'bold' }}
                      />
                    </TableCell>
                    <TableCell>
                      {order.paid_at
                        ? new Date(order.paid_at).toLocaleDateString() + ' ' +
                          new Date(order.paid_at).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
                        : 'N/A'}
                    </TableCell>
                    <TableCell>
                      <Typography variant="body2" noWrap>
                        {order.processed_by || 'N/A'}
                      </Typography>
                    </TableCell>
                    <TableCell align="right">
                      <Button
                        size="small"
                        variant="outlined"
                        startIcon={<Visibility />}
                        onClick={() => handleViewOrder(order)}
                      >
                        View
                      </Button>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </TableContainer>
        )}

        {/* View Order Dialog */}
        <Dialog
          open={Boolean(viewingOrder)}
          onClose={() => setViewingOrder(null)}
          maxWidth="md"
          fullWidth
        >
          {viewingOrder && (
            <>
              <DialogTitle sx={{ bgcolor: 'primary.main', color: 'white', display: 'flex', alignItems: 'center' }}>
                <Description sx={{ mr: 1 }} />
                Order Details - {viewingOrder.order_number}
              </DialogTitle>
              <DialogContent dividers>
                <Grid container spacing={3}>
                  {/* Client Info */}
                  <Grid item xs={12}>
                    <Paper variant="outlined" sx={{ p: 2, bgcolor: 'grey.50' }}>
                      <Typography variant="h6" color="primary" gutterBottom sx={{ display: 'flex', alignItems: 'center' }}>
                        <Person sx={{ mr: 1 }} />
                        Client Information
                      </Typography>
                      <Grid container spacing={2}>
                        <Grid item xs={12} sm={6}>
                          <Typography variant="body2" color="text.secondary">Name</Typography>
                          <Typography variant="body1" fontWeight="medium">{viewingOrder.client?.name}</Typography>
                        </Grid>
                        <Grid item xs={12} sm={6}>
                          <Typography variant="body2" color="text.secondary">Age</Typography>
                          <Typography variant="body1" fontWeight="medium">
                            {viewingOrder.client?.birthdate
                              ? `${calculateAge(viewingOrder.client?.birthdate)} years`
                              : (viewingOrder.client?.age ? `${viewingOrder.client.age} years` : 'N/A')}
                          </Typography>
                        </Grid>
                        <Grid item xs={12} sm={6}>
                          <Typography variant="body2" color="text.secondary">Address</Typography>
                          <Typography variant="body1" fontWeight="medium">{viewingOrder.client?.address || viewingOrder.client?.barangay || 'N/A'}</Typography>
                        </Grid>
                        <Grid item xs={12} sm={6}>
                          <Typography variant="body2" color="text.secondary">Recommended By</Typography>
                          <Typography variant="body1" fontWeight="medium">{viewingOrder.client?.recommended_by || 'N/A'}</Typography>
                        </Grid>
                      </Grid>
                    </Paper>
                  </Grid>

                  {/* Order Items */}
                  <Grid item xs={12}>
                    <Typography variant="h6" color="primary" gutterBottom sx={{ display: 'flex', alignItems: 'center' }}>
                      <ListAlt sx={{ mr: 1 }} />
                      Services
                    </Typography>
                    <TableContainer component={Paper} variant="outlined">
                      <Table size="small">
                        <TableHead sx={{ bgcolor: 'grey.100' }}>
                          <TableRow>
                            <TableCell>Service</TableCell>
                            <TableCell align="center">Qty</TableCell>
                            <TableCell align="right">Price</TableCell>
                            <TableCell align="right">Subtotal</TableCell>
                          </TableRow>
                        </TableHead>
                        <TableBody>
                          {viewingOrder.items?.map((item) => (
                            <TableRow key={item.id}>
                              <TableCell>
                                <Typography variant="body2" fontWeight="medium">{item.service_name}</Typography>
                                {item.subcategory && (
                                  <Typography variant="caption" color="text.secondary">
                                    {item.category && `${item.category} → `}{item.subcategory}
                                  </Typography>
                                )}
                              </TableCell>
                              <TableCell align="center">{item.quantity}</TableCell>
                              <TableCell align="right">₱{parseFloat(item.unit_price).toFixed(2)}</TableCell>
                              <TableCell align="right" sx={{ fontWeight: 'bold' }}>
                                ₱{parseFloat(item.subtotal).toFixed(2)}
                              </TableCell>
                            </TableRow>
                          ))}
                          <TableRow sx={{ bgcolor: 'primary.50' }}>
                            <TableCell colSpan={3} align="right" sx={{ fontWeight: 'bold' }}>TOTAL:</TableCell>
                            <TableCell align="right" sx={{ fontWeight: 'bold', color: 'primary.main', fontSize: '1.1rem' }}>
                              ₱{parseFloat(viewingOrder.total_amount).toFixed(2)}
                            </TableCell>
                          </TableRow>
                        </TableBody>
                      </Table>
                    </TableContainer>
                  </Grid>

                  {/* Payment Info if paid */}
                  {viewingOrder.status === 'paid' && (
                    <Grid item xs={12}>
                      <Paper variant="outlined" sx={{ p: 2, bgcolor: 'success.50', borderColor: 'success.main' }}>
                        <Typography variant="h6" color="success.dark" gutterBottom sx={{ display: 'flex', alignItems: 'center' }}>
                          <CheckCircle sx={{ mr: 1 }} />
                          Payment Details
                        </Typography>
                        <Grid container spacing={2}>
                          <Grid item xs={12} sm={6}>
                            <Typography variant="body2" color="text.secondary">OR Number</Typography>
                            <Typography variant="body1" fontWeight="bold" color="success.dark">
                              {viewingOrder.or_number || 'N/A'}
                            </Typography>
                          </Grid>
                          <Grid item xs={12} sm={6}>
                            <Typography variant="body2" color="text.secondary">Date Paid</Typography>
                            <Typography variant="body1" fontWeight="bold" color="success.dark">
                              {viewingOrder.paid_at ? new Date(viewingOrder.paid_at).toLocaleDateString() : 'N/A'}
                            </Typography>
                          </Grid>
                          <Grid item xs={12}>
                            <Typography variant="body2" color="text.secondary">Processed By</Typography>
                            <Typography variant="body1" fontWeight="medium">
                              {viewingOrder.processed_by || 'N/A'}
                            </Typography>
                          </Grid>
                        </Grid>
                      </Paper>
                    </Grid>
                  )}

                  <Grid item xs={12} sx={{ textAlign: 'center' }}>
                    <Chip
                      label={viewingOrder.status === 'paid' ? 'PAID' : 'PENDING'}
                      color={viewingOrder.status === 'paid' ? 'success' : 'warning'}
                      sx={{ fontWeight: 'bold', px: 2 }}
                    />
                  </Grid>
                </Grid>
              </DialogContent>
              <DialogActions sx={{ p: 2 }}>
                <Button onClick={() => setViewingOrder(null)}>Close</Button>
                {viewingOrder.status === 'pending' && (
                  <Button
                    variant="contained"
                    color="success"
                    startIcon={<AttachMoney />}
                    onClick={() => {
                      openPaymentModal(viewingOrder);
                      setViewingOrder(null);
                    }}
                  >
                    Process Payment
                  </Button>
                )}
              </DialogActions>
            </>
          )}
        </Dialog>

        {/* Process Payment Dialog */}
        <Dialog
          open={Boolean(processingPayment)}
          onClose={() => setProcessingPayment(null)}
          maxWidth="sm"
          fullWidth
        >
          {processingPayment && (
            <>
              <DialogTitle sx={{ bgcolor: 'primary.main', color: 'white', display: 'flex', alignItems: 'center' }}>
                <AttachMoney sx={{ mr: 1 }} />
                Process Payment
              </DialogTitle>
              <DialogContent sx={{ mt: 2 }}>
                <Paper variant="outlined" sx={{ p: 2, mb: 3, bgcolor: 'grey.50' }}>
                  <Typography variant="subtitle2" color="text.secondary" gutterBottom>
                    Payment Summary
                  </Typography>
                  <Typography variant="body1" gutterBottom>
                    <strong>Order Number:</strong> {processingPayment.order_number}
                  </Typography>
                  <Typography variant="body1" gutterBottom>
                    <strong>Client:</strong> {processingPayment.client?.name}
                  </Typography>
                  <Divider sx={{ my: 1 }} />
                  <Typography variant="h5" color="primary.main" fontWeight="bold" align="center">
                    ₱{parseFloat(processingPayment.total_amount).toFixed(2)}
                  </Typography>
                </Paper>

                <TextField
                  fullWidth
                  autoFocus
                  label="Official Receipt (OR) Number"
                  variant="outlined"
                  value={orNumber}
                  onChange={(e) => setOrNumber(e.target.value)}
                  InputProps={{
                    startAdornment: (
                      <InputAdornment position="start">
                        <Receipt />
                      </InputAdornment>
                    ),
                  }}
                  helperText="Please enter the official receipt number for this payment"
                />
              </DialogContent>
              <DialogActions sx={{ p: 2 }}>
                <Button onClick={() => setProcessingPayment(null)}>Cancel</Button>
                <Button
                  variant="contained"
                  color="success"
                  onClick={handleProcessPayment}
                  disabled={loading || !orNumber.trim()}
                  startIcon={loading ? <CircularProgress size={20} /> : <CheckCircle />}
                >
                  Confirm Payment
                </Button>
              </DialogActions>
            </>
          )}
        </Dialog>

        {/* Feedback Snackbar */}
        <Snackbar
          open={Boolean(error || success)}
          autoHideDuration={3000}
          onClose={() => { setError(''); setSuccess(''); }}
          anchorOrigin={{ vertical: 'bottom', horizontal: 'center' }}
        >
          <Alert
            onClose={() => { setError(''); setSuccess(''); }}
            severity={error ? 'error' : 'success'}
            variant="filled"
            sx={{ width: '100%' }}
          >
            {error || success}
          </Alert>
        </Snackbar>
      </Container>
    </Box>
  );
};

export default MunicipalCivilRegistryHome;
