const exportToExcel = async (title, columns, data) => {
  const safeTitle = String(title || 'export')
    .replace(/[\\/:*?"<>|]/g, '-')
    .replace(/\s+/g, ' ')
    .trim();

  const workbook = new ExcelJS.Workbook();
  const sheet = workbook.addWorksheet('List');

  sheet.columns = columns.map((c, idx) => ({
    header: c.header,
    key: `c${idx}`,
    width: Math.max(12, Math.min(40, String(c.header || '').length + 8))
  }));

  sheet.getRow(1).font = { bold: true };

  (data || []).forEach((row) => {
    const values = columns.map((c) => {
      const v = c.accessor ? c.accessor(row) : (c.field ? row[c.field] : '');
      if (v === null || v === undefined) return '';
      return String(v);
    });
    sheet.addRow(values);
  });

  sheet.views = [{ state: 'frozen', ySplit: 1 }];
  sheet.autoFilter = {
    from: { row: 1, column: 1 },
    to: { row: 1, column: Math.max(1, columns.length) }
  };

  const buffer = await workbook.xlsx.writeBuffer();
  const blob = new Blob([buffer], {
    type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
  });
  saveAs(blob, `${safeTitle}.xlsx`);
};
