const useLocalStorage = (key, initial) => {
  const [value, setValue] = useState(() => {
    try {
      const v = localStorage.getItem(key);
      return v ? JSON.parse(v) : initial;
    } catch {
      return initial;
    }
  });
  useEffect(() => {
    try {
      localStorage.setItem(key, JSON.stringify(value));
    } catch {}
  }, [key, value]);
  return [value, setValue];
};

const parseName = (fullName) => {
  if (!fullName) return { firstName: '', middleName: '', lastName: '', suffix: '' };

  // Handle "Last, First Middle Suffix" format (comma separated)
  if (fullName.includes(',')) {
    const [lastNameStr, restStr] = fullName.split(',').map(s => s.trim());
    const parts = restStr.split(' ');
    const lastPart = parts[parts.length - 1];
    const isSuffix = ['Jr', 'Sr', 'II', 'III', 'IV', 'Jr.', 'Sr.'].includes((lastPart || '').replace('.', ''));
    const suffix = isSuffix ? lastPart : '';
    const effectiveParts = isSuffix ? parts.slice(0, -1) : parts;
    
    // For comma format "Last, First Middle", everything before the last word (if > 1 word) is First Name
    // But usually Middle Name is just one word/initial at the end.
    // However, the issue is about "two words in first name".
    // If effectiveParts has > 1 element, we need to decide where to split.
    // Heuristic: If there are multiple parts, assume the last part is Middle Name if it looks like one,
    // otherwise treat most as First Name.
    // Actually, the previous logic: firstName = effectiveParts[0], middleName = rest
    // This fails for "Mary Jane" (First) "D." (Middle). 
    // It makes firstName="Mary", middleName="Jane D."
    
    // Improved logic:
    // If 1 part: First Name only.
    // If >= 2 parts: Last part is Middle Name IF it is a single letter or looks like initial? 
    // OR we just assume Middle Name is the last part? 
    // The user says "The second word became the middle initial." implying "First Second Middle".
    // So "Mary Jane D." was parsed as F:Mary M:Jane D.
    // We want F:Mary Jane M:D.
    
    // Let's assume Middle Name is usually the LAST word of the remaining parts.
    if (effectiveParts.length === 0) return { firstName: '', middleName: '', lastName: lastNameStr, suffix };
    if (effectiveParts.length === 1) return { firstName: effectiveParts[0], middleName: '', lastName: lastNameStr, suffix };
    
    const middleName = effectiveParts[effectiveParts.length - 1];
    const firstName = effectiveParts.slice(0, -1).join(' ');
    
    return { firstName, middleName, lastName: lastNameStr, suffix };
  }

  // Handle "First Middle Last" format
  // This is much harder without a comma. "Mary Jane D. Doe"
  // Previous: last is lastName. Rest is First + Middle.
  // F: effectiveParts[0], M: rest. -> F:Mary M:Jane D.
  // We want F:Mary Jane M:D.
  const parts = fullName.trim().split(' ');
  if (parts.length === 1) return { firstName: parts[0], middleName: '', lastName: '', suffix: '' };
  if (parts.length === 2) return { firstName: parts[0], middleName: '', lastName: parts[1], suffix: '' };
  
  const last = parts[parts.length - 1];
  const isSuffix = ['Jr', 'Sr', 'II', 'III', 'IV', 'Jr.', 'Sr.'].includes(last.replace('.', ''));
  const suffix = isSuffix ? last : '';
  const effectiveParts = isSuffix ? parts.slice(0, -1) : parts;
  
  const lastName = effectiveParts.pop();
  
  // Remaining effectiveParts is [First... Middle]
  if (effectiveParts.length === 0) return { firstName: '', middleName: '', lastName, suffix };
  if (effectiveParts.length === 1) return { firstName: effectiveParts[0], middleName: '', lastName, suffix };

  // Assume last part of remaining is Middle Name
  const middleName = effectiveParts[effectiveParts.length - 1];
  const firstName = effectiveParts.slice(0, -1).join(' ');
  
  return { firstName, middleName, lastName, suffix };
};

const formatName = (fullName) => {
  const { firstName, middleName, lastName, suffix } = parseName(fullName);
  if (!lastName && !firstName) return fullName;
  return `${lastName}, ${firstName}${middleName ? ` ${middleName[0]}.` : ''}${suffix ? ` ${suffix}` : ''}`;
};

