    if (exists) {
      setCustomItemError('This item already exists.');
      return;
    }

    const res = await bploService.createCustomChargeItem(name);
    if (res && res.success) {
      setCustomItemForm({ name: '' });
      setCustomItemError('');
      await refreshCustomItems();
      showSnackbar('Item added successfully', 'success');
    } else {
      setCustomItemError(res?.error || 'Failed to add item');
      showSnackbar(res?.error || 'Failed to add item', 'error');
    }
